<?php include "../includes/header.php"; ?><h2>Task 12 - GET / POST Form</h2><form method="POST" class="card p-4 my-3"><div class="mb-3"><label class="form-label">Product Price</label><input type="text" name="price" class="form-control" required></div><div class="mb-3"><label class="form-label">Quantity</label><input type="text" name="quantity" class="form-control" required></div><button class="btn btn-primary">Calculate</button></form><?php $error="";$total=null;$discount=0;if($_SERVER["REQUEST_METHOD"]=="POST"){$price=trim($_POST["price"]??"");$quantity=trim($_POST["quantity"]??"");if($price===""||$quantity===""){$error="Please enter price and quantity.";}elseif(!is_numeric($price)||!is_numeric($quantity)){$error="Please enter numbers only.";}elseif($price<0||$quantity<0){$error="Negative numbers are not allowed.";}elseif($price==0||$quantity==0){$error="Price and quantity must be greater than zero.";}else{$total=(float)$price*(int)$quantity;$discount=($total<1000)?10:15;$after=$total-($total*$discount/100);}} ?><?php if($error!==""): ?><div class="alert alert-danger"><?php echo htmlspecialchars($error); ?></div><?php endif; ?><?php if($total!==null): ?><div class="result">Total before discount: <b><?php echo number_format($total,2); ?> EGP</b><br>Discount: <b><?php echo $discount; ?>%</b><br>Total after discount: <b><?php echo number_format($after,2); ?> EGP</b></div><?php endif; ?><a href="../index.php" class="btn btn-secondary mt-3">Back</a><?php include "../includes/footer.php"; ?>